insert into public.quiz_questions (seed_key, question, question_type, options, correct_answer, explanation, order_number, metadata, quiz_id) values ($wdthseed$biology:mod04:exam:quiz:q05$wdthseed$, $wdthseed$Cancer chemotherapy often causes hair loss because:$wdthseed$, $wdthseed$multiple_choice$wdthseed$, $wdthseed$["The drugs target all dividing cells, including fast-dividing hair follicle cells","The drugs only work on hair","Hair cells are cancerous","Patients stop eating protein"]$wdthseed$::jsonb, $wdthseed$"The drugs target all dividing cells, including fast-dividing hair follicle cells"$wdthseed$::jsonb, $wdthseed$Chemo poisons rapidly dividing cells. Tumours divide fastest, but hair, gut and bone marrow also divide quickly and suffer collateral damage.$wdthseed$, 5, $wdthseed${"points":1,"topic_tag":"Cell cycle"}$wdthseed$::jsonb, (select id from public.quizzes where seed_key = $wdthseed$biology:mod04:exam:quiz$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set question = excluded.question, question_type = excluded.question_type, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation, order_number = excluded.order_number, metadata = excluded.metadata, quiz_id = excluded.quiz_id;
