insert into public.quiz_questions (seed_key, question, question_type, options, correct_answer, explanation, order_number, metadata, quiz_id) values ($wdthseed$biology:mod07:exam:quiz:q03$wdthseed$, $wdthseed$Waterlogged soils lose fertility partly because denitrifying bacteria:$wdthseed$, $wdthseed$multiple_choice$wdthseed$, $wdthseed$["Fix extra nitrogen","Convert nitrates back to nitrogen gas in anaerobic conditions","Produce oxygen for roots","Eat plant roots"]$wdthseed$::jsonb, $wdthseed$"Convert nitrates back to nitrogen gas in anaerobic conditions"$wdthseed$::jsonb, $wdthseed$Without oxygen, denitrifiers (Pseudomonas) use nitrates for respiration, releasing N2 gas — nitrogen escapes back to the air.$wdthseed$, 3, $wdthseed${"points":1,"topic_tag":"Nitrogen cycle"}$wdthseed$::jsonb, (select id from public.quizzes where seed_key = $wdthseed$biology:mod07:exam:quiz$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set question = excluded.question, question_type = excluded.question_type, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation, order_number = excluded.order_number, metadata = excluded.metadata, quiz_id = excluded.quiz_id;
