insert into public.quiz_questions (seed_key, question, question_type, options, correct_answer, explanation, order_number, metadata, quiz_id) values ($wdthseed$biology:mod09:quiz:q01$wdthseed$, $wdthseed$The correct photosynthesis equation is:$wdthseed$, $wdthseed$multiple_choice$wdthseed$, $wdthseed$["6CO2 + 6H2O →(light/chlorophyll) C6H12O6 + 6O2","C6H12O6 + 6O2 → 6CO2 + 6H2O + energy","6O2 + 6H2O → C6H12O6 + 6CO2","CO2 + H2O → CH4 + O2"]$wdthseed$::jsonb, $wdthseed$"6CO2 + 6H2O →(light/chlorophyll) C6H12O6 + 6O2"$wdthseed$::jsonb, $wdthseed$Photosynthesis builds glucose from CO2 + water using light (oxygen released). The second equation is respiration — the reverse.$wdthseed$, 1, $wdthseed${"points":1,"topic_tag":"Photosynthesis"}$wdthseed$::jsonb, (select id from public.quizzes where seed_key = $wdthseed$biology:mod09:quiz$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set question = excluded.question, question_type = excluded.question_type, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation, order_number = excluded.order_number, metadata = excluded.metadata, quiz_id = excluded.quiz_id;
